final class OrderRepositoryTest extends KernelTestCase
{
    public function testFindsOnlyPendingOrdersOlderThanOneDay(): void
    {
        self::bootKernel();
        $em = self::getContainer()->get(EntityManagerInterface::class);

        $t = static fn (string $ago) => new \DateTimeImmutable($ago);
        $em->persist(new Order('ORD-1', OrderStatus::Pending, $t('-2 days')));
        $em->persist(new Order('ORD-2', OrderStatus::Pending, $t('-1 hour')));
        $em->persist(new Order('ORD-3', OrderStatus::Paid, $t('-3 days')));
        $em->flush();

        $stale = self::getContainer()->get(OrderRepository::class)
            ->findStalePending(new \DateTimeImmutable('-1 day'));

        self::assertSame(['ORD-1'], array_map(fn (Order $o) => $o->number(), $stale));
    }
}

