public function testShippingFallsBackWhenCourierFails(): void
{
    $client = new MockHttpClient([
        new MockResponse('', ['http_code' => 503]),            // the server is sick
        new MockResponse('', ['error' => 'connection timed out']),   // network failure
    ], 'https://api.courier.example');

    $provider = new CourierRateProvider($client, new NullLogger());

    self::assertNull($provider->chargeFor('NY', 500));   // 503: null, not a crash
    self::assertNull($provider->chargeFor('NY', 500));   // timeout: null, not a crash
}

public function chargeFor(string $zone, int $grams): ?int
{
    try {
        $data = $this->client->request('GET', '/v1/rates', [
            'query' => ['zone' => $zone, 'weight' => $grams],
            'timeout' => 2,
        ])->toArray();   // throws on 4xx/5xx, on timeouts and on bad JSON
    } catch (ExceptionInterface $e) {
        $this->logger->warning('Courier rate lookup failed', ['error' => $e->getMessage()]);

        return null;   // no price, but no crash either
    }

    return $data['charge_cents'];
}

public function chargeOrDefault(string $zone, int $grams): int
{
    return $this->chargeFor($zone, $grams) ?? self::DEFAULT_CHARGE_CENTS;   // 800
}

