final class StockConcurrencyTest extends KernelTestCase
{
    public function testTenBuyersSellExactlyOneItem(): void
    {
        $this->seedProduct('SKU-1', stock: 1);
        $startAt = microtime(true) + 3;       // the same start moment for everyone

        $buyers = [];
        for ($i = 1; $i <= 10; ++$i) {
            $buyers[] = $p = new Process([
                PHP_BINARY, 'bin/console', 'app:buy', 'SKU-1',
                "--buyer=$i", "--start-at=$startAt", '--env=test',
            ]);
            $p->start();                      // launch without waiting
        }
        foreach ($buyers as $p) {
            $p->wait();
        }

        self::assertSame(0, $this->stockOf('SKU-1'));      // not negative
        self::assertSame(1, $this->ordersOf('SKU-1'));     // exactly one sale
    }
}

public function buy(string $sku, int $buyerId): void
{
    $stock = (int) $this->connection->fetchOne(
        'SELECT stock FROM product WHERE sku = :sku', ['sku' => $sku],
    );
    if ($stock < 1) {
        throw new OutOfStock($sku);
    }
    // gap: other buyers have read stock = 1 by now too
    $this->connection->executeStatement(
        'UPDATE product SET stock = stock - 1 WHERE sku = :sku', ['sku' => $sku],
    );
    $this->connection->insert('orders', ['sku' => $sku, 'buyer_id' => $buyerId]);
}

public function buy(string $sku, int $buyerId): void
{
    $this->connection->beginTransaction();
    try {
        $updated = $this->connection->executeStatement(
            'UPDATE product SET stock = stock - 1 WHERE sku = :sku AND stock > 0',
            ['sku' => $sku],
        );
        if (0 === $updated) {
            throw new OutOfStock($sku);   // no stock: somebody got there first
        }

        $this->connection->insert('orders', ['sku' => $sku, 'buyer_id' => $buyerId]);
        $this->connection->commit();
    } catch (\Throwable $e) {
        $this->connection->rollBack();
        throw $e;
    }
}

