final class UserMobileMigrationTest extends KernelTestCase
{
    private const BEFORE = 'DoctrineMigrations\Version20261120090000';
    private const AFTER = 'DoctrineMigrations\Version20261120100000';

    public function testExpandKeepsDataAndOldCodeWorking(): void
    {
        $this->migrateTo(self::BEFORE);
        $db = self::getContainer()->get(Connection::class);
        $db->insert('"user"', ['id' => 1, 'phone' => '+1 555-0142']);
        $db->insert('"user"', ['id' => 2, 'phone' => null]);   // corner case

        $this->migrateTo(self::AFTER);

        self::assertSame(2, (int) $db->fetchOne('SELECT COUNT(*) FROM "user"'));
        self::assertSame('+1 555-0142', $db->fetchOne('SELECT phone FROM "user" WHERE id = 1'));
    self::assertSame('+1 555-0142', $db->fetchOne('SELECT mobile FROM "user" WHERE id = 1'));

        // old code doesn't know about mobile: its INSERT must still work
        $db->insert('"user"', ['id' => 3, 'phone' => '+1 555-0187']);
        self::assertNull($db->fetchOne('SELECT mobile FROM "user" WHERE id = 3'));
    }

    private function migrateTo(string $version): void
    {
        (new Process([PHP_BINARY, 'bin/console', 'doctrine:migrations:migrate', $version,
            '--no-interaction', '--env=test']))->mustRun();
    }
}

